def _attach_property_decision_summary(property_obj: TripProperty) -> Any:
    preferences = list(
        property_obj.preferences.select_related("family_group", "updated_by").all()
    )
    counts = {"LOVE": 0, "MAYBE": 0, "PASS": 0}
    for preference in preferences:
        counts[preference.stance] += 1

    property_summary = cast(Any, property_obj)
    property_summary.preference_list = preferences
    property_summary.preference_counts = counts
    property_summary.preference_response_count = len(preferences)
    return property_summary


def _get_editable_family_ids(request: HttpRequest, trip: Trip) -> set[str]:
    user = cast(User, request.user)
    family_ids = active_families(trip).values_list("id", flat=True)
    return {
        str(family_id)
        for family_id in FamilyMembership.objects.filter(
            user=user,
            family_id__in=family_ids,
            is_active=True,
        ).values_list("family_id", flat=True)
    }


@login_required
@feature_required("trips")
def property_list(request: HttpRequest, trip_pk: str) -> HttpResponse:
    """
    Display a list of properties for a trip.

    Args:
        request: The HTTP request
        trip_pk: The primary key of the trip

    Returns:
        HttpResponse: The rendered template
    """
    trip = get_object_or_404(Trip, pk=trip_pk, deleted_at__isnull=True)
    _check_trip_permission(request, trip)  # Check permission

    properties = [
        _attach_property_decision_summary(property_obj)
        for property_obj in trip.properties.prefetch_related(
            "preferences__family_group",
            "preferences__updated_by",
        )
    ]
    has_any_preferences = any(
        property_obj.preference_response_count for property_obj in properties
    )

    context = {
        "trip": trip,
        "properties": properties,
        "has_any_preferences": has_any_preferences,
    }

    return render(request, "trips/properties/list.html", context)


@login_required
@feature_required("trips")
def property_detail(request: HttpRequest, trip_pk: str, pk: str) -> HttpResponse:
    """
    Display details of a property.

    Args:
        request: The HTTP request
        trip_pk: The primary key of the trip
        pk: The primary key of the property

    Returns:
        HttpResponse: The rendered template
    """
    trip = get_object_or_404(Trip, pk=trip_pk, deleted_at__isnull=True)
    _check_trip_permission(request, trip)  # Check permission
    property_obj = get_object_or_404(
        TripProperty.objects.prefetch_related(
            "preferences__family_group", "preferences__updated_by"
        ),
        pk=pk,
        trip=trip,
    )
    editable_family_ids = _get_editable_family_ids(request, trip)

    if request.method == "POST":
        family_group_id = request.POST.get("family_group", "")
        stance = request.POST.get("stance", "")
        note = request.POST.get("note", "").strip()

        if family_group_id not in editable_family_ids:
            messages.error(
                request,
                _("You can only update decisions for a family you belong to."),
            )
            return redirect(
                "trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk
            )

        if not active_families(trip).filter(pk=family_group_id).exists():
            messages.error(request, _("That family is not part of this trip."))
            return redirect(
                "trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk
            )

        if stance not in TripPropertyPreference.Stance.values:
            messages.error(request, _("Choose Love, Maybe, or Pass before saving."))
            return redirect(
                "trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk
            )

        try:
            with transaction.atomic():
                TripPropertyPreference.objects.update_or_create(
                    trip_property=property_obj,
                    family_group_id=family_group_id,
                    defaults={
                        "stance": stance,
                        "note": note,
                        "updated_by": request.user,
                    },
                )
            messages.success(request, _("Family decision saved."))
        except Exception as e:
            logger.error(
                "Error saving property preference for trip %s, property %s, family %s: %s",
                trip.pk,
                property_obj.pk,
                family_group_id,
                str(e),
                exc_info=True,
            )
            messages.error(
                request,
                _("Unable to save your decision. Please try again."),
            )
        return redirect("trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk)

    property_obj = cast(Any, _attach_property_decision_summary(property_obj))
    trip_families = list(active_families(trip))
    family_decision_rows = [
        {
            "family": family,
            "preference": next(
                (
                    preference
                    for preference in property_obj.preference_list
                    if preference.family_group_id == family.id
                ),
                None,
            ),
            "can_edit": str(family.id) in editable_family_ids,
        }
        for family in trip_families
    ]
    has_any_preferences = TripPropertyPreference.objects.filter(
        trip_property__trip=trip
    ).exists()

    context = {
        "trip": trip,
        "property": property_obj,
        "family_decision_rows": family_decision_rows,
        "has_any_preferences": has_any_preferences,
        "stance_choices": TripPropertyPreference.Stance.choices,
    }

    return render(request, "trips/properties/detail.html", context)


@login_required
@feature_required("trips")
def property_create(request: HttpRequest, trip_pk: str) -> HttpResponse:
    """
    Create a new property for a trip.

    Args:
        request: The HTTP request
        trip_pk: The primary key of the trip

    Returns:
        HttpResponse: The rendered template or redirect
    """
    trip = get_object_or_404(Trip, pk=trip_pk, deleted_at__isnull=True)
    _check_trip_permission(request, trip)  # Check permission

    if request.method == "POST":
        form = TripPropertyForm(request.POST)
        if form.is_valid():
            try:
                with transaction.atomic():
                    property_obj = form.save(commit=False)
                    property_obj.trip = trip

                    # If this is the first property, set it as primary
                    if not trip.properties.exists():
                        property_obj.is_primary = True

                        # Complete the quest if gamification is enabled
                        if trip.gamification_enabled:
                            user = cast(User, request.user)
                            QuestService.complete_quest(
                                trip, QuestService.QUEST_CHOOSE_PROPERTY, user
                            )

                    property_obj.save()

                    # Send notification about the new property
                    user = cast(User, request.user)
                    TripNotificationService.notify_property_added(property_obj, user)

                    messages.success(request, "Property added successfully!")
                    return redirect("trips:property_list", trip_pk=trip.pk)
            except ValueError as e:
                logger.warning(
                    f"Validation error creating property for trip {trip.id}: {str(e)}"
                )
                messages.error(request, f"Invalid data: {str(e)}")
            except Exception as e:
                logger.error(
                    f"Unexpected error creating property for trip {trip.id}: {str(e)}",
                    exc_info=True,
                )
                messages.error(
                    request,
                    "An unexpected error occurred. Please try again or contact support if the problem persists.",
                )
                # Fall through to re-display form
    else:
        form = TripPropertyForm()

    context = {
        "form": form,
        "trip": trip,
        "title": "Add Property",
        "decision_help_text": _(
            "Shared facts go here. Family votes and notes happen on the property detail page."
        ),
    }

    return render(request, "trips/properties/form.html", context)


