@feature_required("trips")
def property_set_primary(request: HttpRequest, trip_pk: str, pk: str) -> HttpResponse:
    """
    Set a property as the primary property for a trip.

    Args:
        request: The HTTP request
        trip_pk: The primary key of the trip
        pk: The primary key of the property

    Returns:
        HttpResponse: Redirect
    """
    trip = get_object_or_404(Trip, pk=trip_pk, deleted_at__isnull=True)
    _check_trip_permission(request, trip)  # Check permission
    property_obj = get_object_or_404(TripProperty, pk=pk, trip=trip)

    # Add check: Only creator or family admin should set primary? For now, allow any member.

    # Clear primary flag on all properties
    trip.properties.update(is_primary=False)

    # Set this property as primary
    property_obj.is_primary = True
    property_obj.save()

    messages.success(request, f"'{property_obj.name}' set as primary property.")
    return redirect("trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk)
