from __future__ import annotations

from typing import TYPE_CHECKING, Any, Literal, TypedDict, cast

from django.core.exceptions import ObjectDoesNotExist

from family_scheduler.utils.observability import child_span, set_span_attributes
from users.avatar_resolution import (
    resolve_profile_picture_avatar as _get_profile_picture_avatar,
)
from users.avatar_resolution import (
    resolve_user_avatar as _get_user_avatar,
)

if TYPE_CHECKING:
    from uuid import UUID

    from calendars.models import ExternalCalendarAccount, InternalCalendar
    from events.models import Event
    from users.models import Child


class ResolvedDisplayMember(TypedDict):
    id: str | None
    type: Literal["user", "child", "calendar_owner", "creator", "other"]
    name: str
    avatar: str | None
    color: str | None


class ResolvedSourceCalendar(TypedDict):
    id: str | None
    kind: Literal["external", "internal"] | None
    name: str | None
    provider_or_type: str | None


class ResolvedEventColors(TypedDict):
    effective: str
    effective_source: Literal["event", "calendar", "member", "fallback"]
    event_override: str | None
    calendar_override: str | None
    member: str | None
    fallback: str


class ResolvedEventOwnership(TypedDict):
    display_member: ResolvedDisplayMember | None
    ownership_source: Literal[
        "assigned_user",
        "assigned_child",
        "associated_user",
        "associated_child",
        "calendar_owner",
        "creator",
        "fallback",
    ]
    source_calendar: ResolvedSourceCalendar | None
    resolved_colors: ResolvedEventColors


def _placeholder_resolved_colors() -> ResolvedEventColors:
    """Interim value for ownership paths that are immediately re-resolved."""
    return ResolvedEventColors(
        effective="",
        effective_source="fallback",
        event_override=None,
        calendar_override=None,
        member=None,
        fallback="",
    )


def _get_user_color(user: object) -> str | None:
    """Get color from user profile."""
    if not user:
        return None
    try:
        profile = user.profile  # type: ignore[attr-defined]
        return profile.color or None
    except ObjectDoesNotExist:
        return None


def _build_source_calendar(
    calendar: ExternalCalendarAccount | InternalCalendar,
    kind: Literal["external", "internal"],
) -> ResolvedSourceCalendar:
    """Build source calendar metadata from a calendar object."""
    if kind == "external":
        return ResolvedSourceCalendar(
            id=str(calendar.id),
            kind="external",
            name=getattr(calendar, "account_name", None),
            provider_or_type=getattr(calendar, "provider", None),
        )
    else:
        return ResolvedSourceCalendar(
            id=str(calendar.id),
            kind="internal",
            name=getattr(calendar, "name", None),
            provider_or_type=getattr(calendar, "type", None),
        )


def _hash_to_color(key: str) -> str:
    palette = [
        "#FF6B6B",
        "#4ECDC4",
        "#45B7D1",
        "#96CEB4",
        "#FFEAA7",
        "#DDA5E9",
        "#FF8CC8",
        "#6C5CE7",
    ]
    hash_value = sum(ord(char) for char in key)
    return palette[hash_value % len(palette)]


def _get_calendar_color_override(
    calendar: ExternalCalendarAccount | InternalCalendar | None,
) -> str | None:
    if not calendar:
        return None
    override = getattr(calendar, "display_color_override", None)
    return override or None


def _build_resolved_event_colors(
    event: Event,
    calendar: ExternalCalendarAccount | InternalCalendar | None,
    display_member: ResolvedDisplayMember | None,
) -> ResolvedEventColors:
    event_override = getattr(event, "display_color_override", None) or None
    calendar_override = _get_calendar_color_override(calendar)
    member_color = display_member["color"] if display_member else None
    fallback = _hash_to_color(str(event.id))

    if event_override:
        effective = event_override
        effective_source: Literal["event", "calendar", "member", "fallback"] = "event"
    elif calendar_override:
        effective = calendar_override
        effective_source = "calendar"
    elif member_color:
        effective = member_color
        effective_source = "member"
    else:
        effective = fallback
        effective_source = "fallback"

    return ResolvedEventColors(
        effective=effective,
        effective_source=effective_source,
        event_override=event_override,
        calendar_override=calendar_override,
        member=member_color,
        fallback=fallback,
    )


def _with_resolved_colors(
    event: Event,
    ownership: ResolvedEventOwnership,
    calendar: ExternalCalendarAccount | InternalCalendar | None,
) -> ResolvedEventOwnership:
    ownership["resolved_colors"] = _build_resolved_event_colors(
        event,
        calendar=calendar,
        display_member=ownership["display_member"],
    )
    return ownership


def _resolve_from_explicit_assignment(
    event: Event,
    calendar: ExternalCalendarAccount | InternalCalendar | None,
    request_host: str | None = None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> ResolvedEventOwnership | None:
    if calendar is None:
        source_cal = None
    else:
        source_cal = _build_source_calendar(
            calendar,
            "external"
            if getattr(getattr(calendar, "_meta", None), "model_name", "")
            == "externalcalendaraccount"
            else "internal",
        )

    assigned_user = getattr(event, "assigned_user", None)
    if assigned_user:
        return ResolvedEventOwnership(
            display_member=ResolvedDisplayMember(
                id=str(assigned_user.id),
                type="user",
                name=assigned_user.get_full_name() or assigned_user.username,
                avatar=_get_user_avatar(
                    assigned_user,
                    request_host=request_host,
                    cache=cache,
                ),
                color=_get_user_color(assigned_user),
            ),
            ownership_source="assigned_user",
            source_calendar=source_cal,
            resolved_colors=_placeholder_resolved_colors(),
        )

    assigned_child = getattr(event, "assigned_child", None)
    if assigned_child:
        child = cast("Child", assigned_child)
        return ResolvedEventOwnership(
            display_member=ResolvedDisplayMember(
                id=f"child_{child.id}",
                type="child",
                name=f"{child.first_name} {child.last_name}",
                avatar=_get_profile_picture_avatar(
                    child.profile_picture,
                    request_host=request_host,
                    cache=cache,
                ),
                color=child.color or None,
            ),
            ownership_source="assigned_child",
            source_calendar=source_cal,
            resolved_colors=_placeholder_resolved_colors(),
        )

    return None


def _resolve_from_calendar(
    calendar: ExternalCalendarAccount | InternalCalendar,
    kind: Literal["external", "internal"],
    request_host: str | None = None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> ResolvedEventOwnership | None:
    """Resolve display ownership from calendar associations before color."""
    source_cal = _build_source_calendar(calendar, kind)

    assoc_users = list(calendar.associated_users.all())
    creator_id = getattr(calendar, "user_id", None)
    if creator_id is not None:
        assoc_users = [u for u in assoc_users if u.id != creator_id]
    if assoc_users:
        assoc_user = assoc_users[0]
        return ResolvedEventOwnership(
            display_member=ResolvedDisplayMember(
                id=str(assoc_user.id),
                type="user",
                name=assoc_user.get_full_name() or assoc_user.username,
                avatar=_get_user_avatar(
                    assoc_user, request_host=request_host, cache=cache
                ),
                color=_get_user_color(assoc_user),
            ),
            ownership_source="associated_user",
            source_calendar=source_cal,
            resolved_colors=_placeholder_resolved_colors(),
        )

    if hasattr(calendar, "associated_children"):
        assoc_children = list(calendar.associated_children.all())
        if assoc_children:
            child = assoc_children[0]
            return ResolvedEventOwnership(
                display_member=ResolvedDisplayMember(
                    id=f"child_{child.id}",
                    type="child",
                    name=f"{child.first_name} {child.last_name}",
                    avatar=_get_profile_picture_avatar(
                        child.profile_picture,
                        request_host=request_host,
                        cache=cache,
                    ),
                    color=child.color or None,
                ),
                ownership_source="associated_child",
                source_calendar=source_cal,
                resolved_colors=_placeholder_resolved_colors(),
            )

    if hasattr(calendar, "user") and calendar.user:
        owner_name = calendar.user.get_full_name() or source_cal["name"] or "Unknown"
        return ResolvedEventOwnership(
            display_member=ResolvedDisplayMember(
                id=str(calendar.user.id),
                type="calendar_owner",
                name=owner_name,
                avatar=_get_user_avatar(
                    calendar.user, request_host=request_host, cache=cache
                ),
                color=_get_user_color(calendar.user),
            ),
            ownership_source="calendar_owner",
            source_calendar=source_cal,
            resolved_colors=_placeholder_resolved_colors(),
        )

    return None


def resolve_event_ownership(
    event: Event,
    external_calendars_dict: dict[str, ExternalCalendarAccount] | None = None,
    external_calendar_lookup: dict[str, ExternalCalendarAccount] | None = None,
    internal_calendars_dict: dict[UUID, InternalCalendar] | None = None,
    request_host: str | None = None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> ResolvedEventOwnership:
    """Resolve event ownership metadata following the same priority chain
    as ``get_event_member_color``.

    Returns a ``ResolvedEventOwnership`` dict with ``display_member``,
    ``ownership_source``, and ``source_calendar``.
    """
    external_calendars_dict = external_calendars_dict or {}
    internal_calendars_dict = internal_calendars_dict or {}
    if external_calendar_lookup is None:
        from users.utils import _build_external_calendar_lookup

        external_calendar_lookup = _build_external_calendar_lookup(
            external_calendars_dict
        )

    if getattr(event, "is_external", False) and event.calendar_id:
        calendar_kind = "external"
    elif event.internal_calendar_id:
        calendar_kind = "internal"
    else:
        calendar_kind = "none"

    with child_span(
        "api.events.serialize.resolve_ownership",
        calendar_kind=calendar_kind,
        has_event_override=bool(getattr(event, "display_color_override", None)),
        used_calendar_lookup=bool(external_calendar_lookup),
    ) as ownership_span:
        set_span_attributes(
            ownership_span,
            external_calendar_count=len(external_calendar_lookup),
            internal_calendar_count=len(internal_calendars_dict),
        )

        source_calendar_obj: ExternalCalendarAccount | InternalCalendar | None = None
        if getattr(event, "is_external", False) and event.calendar_id:
            calendar_obj = external_calendar_lookup.get(str(event.calendar_id))
            if calendar_obj:
                source_calendar_obj = calendar_obj

        # For internal calendar events
        calendar_obj = None
        if event.internal_calendar_id:
            calendar_obj = internal_calendars_dict.get(event.internal_calendar_id)
            if not calendar_obj:
                calendar_obj = getattr(event, "internal_calendar", None)

        if calendar_obj:
            source_calendar_obj = calendar_obj

        explicit_assignment = _resolve_from_explicit_assignment(
            event,
            source_calendar_obj,
            request_host=request_host,
            cache=cache,
        )
        if explicit_assignment:
            return _with_resolved_colors(
                event,
                explicit_assignment,
                source_calendar_obj,
            )

        if source_calendar_obj:
            source_calendar_kind: Literal["external", "internal"] = (
                "external"
                if getattr(
                    getattr(source_calendar_obj, "_meta", None), "model_name", ""
                )
                == "externalcalendaraccount"
                else "internal"
            )
            result = _resolve_from_calendar(
                source_calendar_obj,
                source_calendar_kind,
                request_host=request_host,
                cache=cache,
            )
            if result:
                return _with_resolved_colors(event, result, source_calendar_obj)

            # When a calendar exists but has no explicit associations, keep the
            # source calendar metadata while falling back to the creator.
            try:
                creator = event.creator
            except ObjectDoesNotExist:
                creator = None
            if creator:
                color = _get_user_color(creator)
                return _with_resolved_colors(
                    event,
                    ResolvedEventOwnership(
                        display_member=ResolvedDisplayMember(
                            id=str(creator.id),
                            type="creator",
                            name=creator.get_full_name() or creator.username,
                            avatar=_get_user_avatar(
                                creator,
                                request_host=request_host,
                                cache=cache,
                            ),
                            color=color,
                        ),
                        ownership_source="creator",
                        source_calendar=_build_source_calendar(
                            source_calendar_obj,
                            source_calendar_kind,
                        ),
                        resolved_colors=ResolvedEventColors(
                            effective="",
                            effective_source="fallback",
                            event_override=None,
                            calendar_override=None,
                            member=None,
                            fallback="",
                        ),
                    ),
                    source_calendar_obj,
                )

        # For manually created events or external events without colored ownership
        try:
            creator = event.creator
        except ObjectDoesNotExist:
            creator = None

        if creator:
            color = _get_user_color(creator)
            return _with_resolved_colors(
                event,
                ResolvedEventOwnership(
                    display_member=ResolvedDisplayMember(
                        id=str(creator.id),
                        type="creator",
                        name=creator.get_full_name() or creator.username,
                        avatar=_get_user_avatar(
                            creator, request_host=request_host, cache=cache
                        ),
                        color=color,
                    ),
                    ownership_source="creator",
                    source_calendar=None,
                    resolved_colors=ResolvedEventColors(
                        effective="",
                        effective_source="fallback",
                        event_override=None,
                        calendar_override=None,
                        member=None,
                        fallback="",
                    ),
                ),
                source_calendar_obj,
            )

        # Final fallback - no creator, no calendar
        return _with_resolved_colors(
            event,
            ResolvedEventOwnership(
                display_member=None,
                ownership_source="fallback",
                source_calendar=None,
                resolved_colors=ResolvedEventColors(
                    effective="",
                    effective_source="fallback",
                    event_override=None,
                    calendar_override=None,
                    member=None,
                    fallback="",
                ),
            ),
            source_calendar_obj,
        )
