from django.contrib import admin

from .event_types import ALL_EVENT_TYPES, EVENT_TYPE_NAMES
from .models import WebhookDelivery, WebhookDestination


@admin.register(WebhookDestination)
class WebhookDestinationAdmin(admin.ModelAdmin):
    list_display = [
        "name",
        "destination_type",
        "is_active",
        "subscribed_events_display",
        "created_at",
    ]
    list_filter = ["destination_type", "is_active"]
    search_fields = ["name", "url"]
    readonly_fields = ["created_at", "updated_at"]

    fieldsets = (
        (
            "Destination Configuration",
            {
                "fields": (
                    "name",
                    "destination_type",
                    "url",
                    "is_active",
                )
            },
        ),
        (
            "Event Subscriptions",
            {
                "fields": ("subscribed_events",),
                "description": f"Available events: {', '.join(ALL_EVENT_TYPES)}",
            },
        ),
        (
            "Security",
            {
                "fields": ("secret_key",),
                "classes": ("collapse",),
                "description": "Optional: Secret key for HMAC signing webhooks",
            },
        ),
        (
            "Metadata",
            {
                "fields": ("created_by", "created_at", "updated_at"),
                "classes": ("collapse",),
            },
        ),
    )

    @admin.display(description="Subscribed Events")
    def subscribed_events_display(self, obj):
        events = obj.subscribed_events or []
        return ", ".join(EVENT_TYPE_NAMES.get(e, e) for e in events)

    def save_model(self, request, obj, form, change):
        if not change:  # New object
            obj.created_by = request.user
        super().save_model(request, obj, form, change)


