@login_required
def manage_external_account_visibility(request: HttpRequest, pk: str) -> HttpResponse:
    """
    Allow the user to manage visibility rules for a specific external account.
    Handles GET (display formset) and POST (save formset).
    """
    user = cast(User, request.user)  # login_required guarantees User
    account = get_object_or_404(ExternalCalendarAccount, pk=pk, user=user)

    # Create a FormSet for the visibility rules related to this account
    visibility_rule_formset = modelformset_factory(
        ExternalAccountVisibility,
        form=ExternalAccountVisibilityRuleForm,  # Ensure this uses the correct form name
        extra=1,  # Allow adding one new rule at a time
        can_delete=True,  # Allow deleting existing rules
    )

    # Pass the request user to the formset's forms for filtering choices
    formset_kwargs = {"form_kwargs": {"user": user}}

    if request.method == "POST":
        formset = visibility_rule_formset(
            request.POST,
            queryset=ExternalAccountVisibility.objects.filter(external_account=account),
            **formset_kwargs,  # type: ignore[arg-type]
        )
        if formset.is_valid():
            instances = formset.save(commit=False)
            for instance in instances:
                # Associate each new/updated rule with the current account
                instance.external_account = account
                instance.save()
            # Handle deletions
            formset.save_m2m()  # Needed for M2M if form had them, but good practice
            for obj in formset.deleted_objects:
                obj.delete()

            messages.success(
                request, f"Visibility rules for {account.account_email} updated."
            )
            return redirect("calendars:external_account_list")
        else:
            # Log formset errors for debugging
            logger = logging.getLogger(__name__)
            logger.error(f"Formset errors for account {account.pk}: {formset.errors}")
            logger.error(f"Non-form errors: {formset.non_form_errors()}")
            messages.error(request, "Please correct the errors below.")
    else:
        formset = visibility_rule_formset(
            queryset=ExternalAccountVisibility.objects.filter(external_account=account),
            **formset_kwargs,  # type: ignore[arg-type]
        )

    context = {
        "account": account,
        "formset": formset,  # Pass formset to context
    }
    # Template needs update to render formset
    return render(request, "calendars/manage_external_account_visibility.html", context)


@login_required
@require_POST  # Ensure disconnection happens via POST request
def disconnect_external_account(request: HttpRequest, pk: str) -> HttpResponse:
    """
    Disconnect an external account, remove tokens, and associated data.
    """
    user = cast(User, request.user)  # login_required guarantees User
    account = get_object_or_404(ExternalCalendarAccount, pk=pk, user=user)
    account_email = account.account_email  # Store email before deleting

    # TODO: Add more robust deletion logic if needed (e.g., revoke token via API)
    # For now, just delete the local records

    with transaction.atomic():
        # Delete associated visibility rules first
        ExternalAccountVisibility.objects.filter(external_account=account).delete()
        # Delete sync logs, modified/deleted event records if necessary (similar to external_calendar_delete)
        SyncLog.objects.filter(calendar=account).delete()  # Assuming 'calendar' FK name
        ModifiedExternalEvent.objects.filter(calendar=account).delete()
        DeletedExternalEvent.objects.filter(calendar=account).delete()
        # Delete future events linked by string calendar_id (not a FK, no CASCADE).
        # Past events are kept as history.
        Event.secure.for_user(user).filter(
            is_external=True,
            calendar_id=str(account.id),
            external_source=account.provider,
            start_time__gte=timezone.now(),
        ).delete()
        # Delete the account itself
        account.delete()

    messages.success(request, f"Account {account_email} disconnected successfully.")
    return redirect("calendars:external_account_list")


