import logging

from django.db.models.signals import post_save
from django.dispatch import receiver

from notifications.services.notification_service import NotificationService
from payments.models import Invoice, Subscription

logger = logging.getLogger(__name__)


@receiver(post_save, sender=Subscription)
def notify_subscription_change(sender, instance, created, **kwargs):
    """Send notification when subscription is created or updated"""
    if created:
        notification_type = "SUBSCRIPTION_CREATED"
        title = "Welcome to Family Scheduler Premium!"
        message = f"Your family subscription to {instance.tier.display_name} has been activated. Enjoy all the premium features!"
    else:
        # For updates, we'll rely on the webhook handlers in tasks.py
        # which have access to the previous state from Stripe
        return

    # Get all admin users in the family
    admin_users = instance.family.memberships.filter(
        is_admin=True, left_at__isnull=True
    ).select_related("user")

    for membership in admin_users:
        try:
            NotificationService.create_notification(
                user=membership.user,
                title=title,
                message=message,
                notification_type=notification_type,
                priority="HIGH" if "CANCELED" in notification_type else "MEDIUM",
                data={
                    "action_url": "/settings/billing/",
                    "subscription_id": str(instance.id),
                },
            )
        except Exception as e:
            logger.error(f"Error sending subscription notification: {e}")


@receiver(post_save, sender=Invoice)
def notify_invoice_status(sender, instance, created, **kwargs):
    """Send notification when invoice is paid or fails"""
    # Only notify for new invoices with specific statuses
    # Updates will be handled by webhook handlers
    if not created:
        return

    if instance.status == "paid":
        notification_type = "PAYMENT_SUCCESSFUL"
        title = "Payment Received"
        message = f"We've received your payment of ${instance.amount_paid}. Thank you!"
        priority = "LOW"
    elif instance.status in ["open", "uncollectible"]:
        notification_type = "PAYMENT_FAILED"
        title = "Payment Failed"
        message = f"We were unable to process your payment of ${instance.amount_due}. Please update your payment method."
        priority = "HIGH"
    else:
        return  # Don't notify for other statuses

    # Get all admin users in the family
    admin_users = instance.subscription.family.memberships.filter(
        is_admin=True, left_at__isnull=True
    ).select_related("user")

    for membership in admin_users:
        try:
            NotificationService.create_notification(
                user=membership.user,
                title=title,
                message=message,
                notification_type=notification_type,
                priority=priority,
                data={
                    "action_url": "/settings/billing/",
                    "invoice_id": str(instance.id),
                    "amount": str(instance.amount_due),
                },
            )
        except Exception as e:
            logger.error(f"Error sending invoice notification: {e}")

