from datetime import datetime
from datetime import timezone as dt_timezone
from decimal import Decimal
from typing import Any

import stripe
from django.conf import settings
from django.contrib.auth.models import User

from payments.models import (
    Invoice,
    PaymentEvent,
    PaymentMethod,
    StripeCustomer,
    Subscription,
    SubscriptionTier,
)
from users.models import FamilyGroup

logger = logging.getLogger(__name__)


def _get_subscription_period(
    stripe_subscription: stripe.Subscription | dict[str, Any],
) -> tuple[datetime, datetime]:
    """Extract current period from Stripe subscription items.

    Stripe API v2025+ removed current_period_start/end from the top-level
    Subscription object. These fields now live on subscription items.
    """
    item = stripe_subscription["items"]["data"][0]
    period_start = datetime.fromtimestamp(
        item["current_period_start"], tz=dt_timezone.utc
    )
    period_end = datetime.fromtimestamp(item["current_period_end"], tz=dt_timezone.utc)
    return (period_start, period_end)


class StripeService:
    """Service class for all Stripe-related operations"""

    @staticmethod
    def initialize_stripe():
        """Initialize Stripe with API key using lazy initialization.

        This method ensures the API key is only set when needed, preventing
        exposure of sensitive credentials in module-level initialization.
        """
        if not stripe.api_key:
            stripe.api_key = settings.STRIPE_SECRET_KEY
            if not stripe.api_key:
                raise ValueError("STRIPE_SECRET_KEY is not configured")

            # Validate API key format and environment
            if stripe.api_key.startswith("sk_test_") and not settings.DEBUG:
                raise ValueError("Test API key detected in production environment")
            elif stripe.api_key.startswith("sk_live_") and settings.DEBUG:
                raise ValueError("Live API key detected in development environment")
            elif not (
                stripe.api_key.startswith("sk_test_")
                or stripe.api_key.startswith("sk_live_")
            ):
                raise ValueError("Invalid Stripe API key format")

    @staticmethod
    def create_customer(user: User) -> StripeCustomer:
        """Create Stripe customer for user"""
        StripeService.initialize_stripe()

        try:
            # Check if customer already exists
            if hasattr(user, "stripe_customer"):
                return user.stripe_customer

            # Create customer in Stripe with idempotency key
            idempotency_key = f"create_customer_{user.id}"
            stripe_customer = stripe.Customer.create(
                email=user.email,
                name=f"{user.first_name} {user.last_name}",
                metadata={"user_id": str(user.id), "username": user.username},
                idempotency_key=idempotency_key,
            )

            # Create customer in database
            customer = StripeCustomer.objects.create(
                user=user, stripe_customer_id=stripe_customer.id
            )

            logger.info(
                f"Created Stripe customer {stripe_customer.id} for user {user.id}"
            )
            return customer

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating customer: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating Stripe customer: {e}")
            raise

    @staticmethod
    def create_subscription(
        family: FamilyGroup,
        customer: StripeCustomer,
        tier: SubscriptionTier,
        trial_days: int = 14,
    ) -> Subscription:
        """Create subscription for family with specified tier"""
        StripeService.initialize_stripe()

        try:
            # Check if family already has subscription
            if hasattr(family, "subscription"):
                raise ValueError(f"Family {family.id} already has a subscription")

            # Create subscription in Stripe with idempotency key
            import time

            idempotency_key = f"create_subscription_{family.id}_{int(time.time())}"
            stripe_subscription = stripe.Subscription.create(
                customer=customer.stripe_customer_id,
                items=[{"price": tier.stripe_price_id}],
                metadata={
                    "family_id": str(family.id),
                    "family_name": family.name,
                    "tier": tier.name,
                },
                trial_period_days=trial_days,
                idempotency_key=idempotency_key,
            )

            period_start, period_end = _get_subscription_period(stripe_subscription)

            # Create subscription in database
            subscription = Subscription.objects.create(
                family=family,
                customer=customer,
                tier=tier,
                stripe_subscription_id=stripe_subscription.id,
                status=stripe_subscription.status,
                current_period_start=period_start,
                current_period_end=period_end,
                trial_end=datetime.fromtimestamp(
                    stripe_subscription.trial_end, tz=dt_timezone.utc
                )
                if stripe_subscription.trial_end
                else None,
            )

            logger.info(
                f"Created subscription {stripe_subscription.id} for family {family.id}"
            )
            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating subscription: {e}")
            raise

    @staticmethod
    def upgrade_subscription(
        subscription: Subscription, new_tier: SubscriptionTier
    ) -> Subscription:
        """Upgrade subscription to a new tier"""
        StripeService.initialize_stripe()

        try:
            # Get current subscription items
            stripe_subscription = stripe.Subscription.retrieve(
                subscription.stripe_subscription_id
            )

            # Update subscription in Stripe
            stripe_subscription = stripe.Subscription.modify(
                subscription.stripe_subscription_id,
                items=[
                    {
                        "id": stripe_subscription["items"]["data"][0].id,
                        "price": new_tier.stripe_price_id,
                    }
                ],
                proration_behavior="create_prorations",
                metadata={
                    "family_id": str(subscription.family.id),
                    "family_name": subscription.family.name,
                    "tier": new_tier.name,
                    "previous_tier": subscription.tier.name,
                },
            )

            # Update subscription in database
            subscription.tier = new_tier
            subscription.status = stripe_subscription.status
            subscription.save()

            logger.info(f"Upgraded subscription {subscription.id} to {new_tier.name}")
            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error upgrading subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error upgrading subscription: {e}")
            raise

    @staticmethod
    def cancel_subscription(
        subscription: Subscription, immediately: bool = False
    ) -> Subscription:
        """Cancel subscription (immediate or at period end)"""
        StripeService.initialize_stripe()

        try:
            if immediately:
                # Cancel immediately
                stripe.Subscription.delete(subscription.stripe_subscription_id)  # type: ignore[arg-type]
                subscription.status = "canceled"
                subscription.save()
                logger.info(f"Canceled subscription {subscription.id} immediately")
            else:
                # Cancel at period end
                stripe.Subscription.modify(
                    subscription.stripe_subscription_id, cancel_at_period_end=True
                )
                subscription.cancel_at_period_end = True
                subscription.save()
                logger.info(
                    f"Scheduled subscription {subscription.id} to cancel at period end"
                )

            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error canceling subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error canceling subscription: {e}")
            raise

    @staticmethod
    def reactivate_subscription(subscription: Subscription) -> Subscription:
        """Reactivate a subscription scheduled for cancellation"""
        StripeService.initialize_stripe()

        try:
            if not subscription.cancel_at_period_end:
                raise ValueError("Subscription is not scheduled for cancellation")

            # Reactivate in Stripe
            stripe.Subscription.modify(
                subscription.stripe_subscription_id, cancel_at_period_end=False
            )

            # Update database
            subscription.cancel_at_period_end = False
            subscription.save()

            logger.info(f"Reactivated subscription {subscription.id}")
            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error reactivating subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error reactivating subscription: {e}")
            raise

    @staticmethod
    def create_setup_intent(customer: StripeCustomer) -> dict[str, Any]:
        """Create a setup intent for adding payment methods"""
        StripeService.initialize_stripe()

        try:
            import time

            idempotency_key = f"setup_intent_{customer.user.id}_{int(time.time())}"
            setup_intent = stripe.SetupIntent.create(
                customer=customer.stripe_customer_id,
                metadata={
                    "customer_id": str(customer.id),
                    "user_id": str(customer.user.id),
                },
                idempotency_key=idempotency_key,
            )

            return {
                "client_secret": setup_intent.client_secret,
                "setup_intent_id": setup_intent.id,
            }

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating setup intent: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating setup intent: {e}")
            raise

    @staticmethod
    def add_payment_method(
        customer: StripeCustomer, payment_method_id: str, set_as_default: bool = True
    ) -> PaymentMethod:
        """Add a payment method to customer"""
        StripeService.initialize_stripe()

        try:
            # Attach payment method to customer
            stripe_pm = stripe.PaymentMethod.attach(
                payment_method_id, customer=customer.stripe_customer_id
            )

            # Set as default if requested
            if set_as_default:
                stripe.Customer.modify(
                    customer.stripe_customer_id,
                    invoice_settings={"default_payment_method": payment_method_id},
                )

            # Create in database
            card = stripe_pm.card
            payment_method = PaymentMethod.objects.create(
                customer=customer,
                stripe_payment_method_id=payment_method_id,
                type=stripe_pm.type,
                last4=card.last4 if stripe_pm.type == "card" and card else "",
                brand=card.brand if stripe_pm.type == "card" and card else None,
                is_default=set_as_default,
            )

            logger.info(
                f"Added payment method {payment_method_id} for customer {customer.id}"
            )
            return payment_method

        except stripe.StripeError as e:
            logger.error(f"Stripe error adding payment method: {e}")
            raise
        except Exception as e:
            logger.error(f"Error adding payment method: {e}")
            raise

    @staticmethod
    def remove_payment_method(payment_method: PaymentMethod) -> None:
        """Remove a payment method"""
        StripeService.initialize_stripe()

        try:
            # Detach from Stripe
            stripe.PaymentMethod.detach(payment_method.stripe_payment_method_id)

            # Delete from database
            payment_method.delete()

            logger.info(f"Removed payment method {payment_method.id}")

        except stripe.StripeError as e:
            logger.error(f"Stripe error removing payment method: {e}")
            raise
        except Exception as e:
            logger.error(f"Error removing payment method: {e}")
            raise

    @staticmethod
    def create_billing_portal_session(customer: StripeCustomer, return_url: str) -> str:
        """Create Stripe billing portal session for customer self-service"""
        StripeService.initialize_stripe()

        try:
            session = stripe.billing_portal.Session.create(
                customer=customer.stripe_customer_id, return_url=return_url
            )

            return session.url

        except stripe.StripeError as e:
            logger.error(f"Stripe error creating billing portal session: {e}")
            raise
        except Exception as e:
            logger.error(f"Error creating billing portal session: {e}")
            raise

    @staticmethod
    def sync_subscription_status(subscription: Subscription) -> Subscription:
        """Sync subscription status from Stripe"""
        StripeService.initialize_stripe()

        try:
            # Get subscription from Stripe
            stripe_subscription = stripe.Subscription.retrieve(
                subscription.stripe_subscription_id
            )

            period_start, period_end = _get_subscription_period(stripe_subscription)

            # Update local subscription
            subscription.status = stripe_subscription.status
            subscription.current_period_start = period_start
            subscription.current_period_end = period_end
            subscription.cancel_at_period_end = stripe_subscription.cancel_at_period_end
            subscription.save()

            logger.info(
                f"Synced subscription {subscription.id} status: {subscription.status}"
            )
            return subscription

        except stripe.StripeError as e:
            logger.error(f"Stripe error syncing subscription: {e}")
            raise
        except Exception as e:
            logger.error(f"Error syncing subscription: {e}")
            raise

    @staticmethod
    def create_invoice_from_stripe(stripe_invoice: dict[str, Any]) -> Invoice | None:
        """Create or update invoice from Stripe webhook data"""
        try:
            # Find subscription
            subscription = Subscription.objects.filter(
                stripe_subscription_id=stripe_invoice["subscription"]
            ).first()

            if not subscription:
                logger.warning(
                    f"Subscription not found for invoice {stripe_invoice['id']}"
                )
                return None

            # Create or update invoice
            invoice, created = Invoice.objects.update_or_create(
                stripe_invoice_id=stripe_invoice["id"],
                defaults={
                    "subscription": subscription,
                    "amount_paid": Decimal(str(stripe_invoice.get("amount_paid", 0)))
                    / Decimal("100"),  # Convert from cents
                    "amount_due": Decimal(str(stripe_invoice.get("amount_due", 0)))
                    / Decimal("100"),
                    "currency": stripe_invoice["currency"],
                    "status": stripe_invoice["status"],
                    "period_start": datetime.fromtimestamp(
                        stripe_invoice["period_start"], tz=dt_timezone.utc
                    ),
                    "period_end": datetime.fromtimestamp(
