from payments.models import PaymentEvent


class Command(BaseCommand):
    help = "Check for duplicate webhook events and optionally clean them up"

    def add_arguments(self, parser):
        parser.add_argument(
            "--fix",
            action="store_true",
            help="Remove duplicate events, keeping only the processed one",
        )

    def handle(self, *args, **options):
        # Find duplicate events
        duplicates = (
            PaymentEvent.objects.values("stripe_event_id")
            .annotate(count=Count("id"))
            .filter(count__gt=1)
        )

        if not duplicates:
            self.stdout.write(self.style.SUCCESS("No duplicate webhook events found."))
            return

        self.stdout.write(
            self.style.WARNING(f"Found {len(duplicates)} duplicate event IDs:")
        )

        total_removed = 0
        event_stats: dict[str, int] = defaultdict(int)

        for dup in duplicates:
            stripe_event_id = dup["stripe_event_id"]
            events = PaymentEvent.objects.filter(
                stripe_event_id=stripe_event_id
            ).order_by("-processed", "-created_at")

            self.stdout.write(f"\nEvent ID: {stripe_event_id}")
            self.stdout.write(f"  Occurrences: {dup['count']}")

            # Keep the first processed event, or the most recent if none processed
            keep_event = events.first()
            remove_events = list(events[1:])

            for event in events:
                status = "KEEP" if event == keep_event else "REMOVE"
                self.stdout.write(
                    f"  - {event.id} | {event.event_type} | "
                    f"Processed: {event.processed} | "
                    f"Created: {event.created_at} | {status}"
                )
                event_stats[event.event_type] += 1

            if options["fix"] and remove_events:
                for event in remove_events:
                    event.delete()
                    total_removed += 1
                self.stdout.write(
                    self.style.SUCCESS(f"  Removed {len(remove_events)} duplicates")
                )

        self.stdout.write("\nEvent Type Summary:")
        for event_type, count in sorted(event_stats.items()):
            self.stdout.write(f"  {event_type}: {count}")

        if options["fix"]:
            self.stdout.write(
                self.style.SUCCESS(f"\nTotal events removed: {total_removed}")
            )
        else:
            self.stdout.write(
                self.style.WARNING("\nRun with --fix flag to remove duplicate events")
            )

