class PaymentMethodViewSet(viewsets.ModelViewSet[PaymentMethod]):
    """ViewSet for payment methods"""

    serializer_class = PaymentMethodSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self) -> QuerySet[PaymentMethod]:
        user = cast(User, self.request.user)
        if hasattr(user, "stripe_customer"):
            return PaymentMethod.objects.filter(customer=user.stripe_customer)
        return PaymentMethod.objects.none()

    def destroy(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        """Remove a payment method"""
        payment_method = self.get_object()

        # Check if it's the only payment method
        other_methods = (
            PaymentMethod.objects.filter(customer=payment_method.customer)
            .exclude(id=payment_method.id)
            .exists()
        )

        if (
            not other_methods
            and payment_method.customer.subscriptions.filter(
                status__in=["active", "trialing"]
            ).exists()
        ):
            return Response(
                {
                    "error": "Cannot remove the only payment method with active subscriptions"
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            StripeService.remove_payment_method(payment_method)
            record_wide_event(
                request=request,
                operation="payment_method.destroy",
                outcome="success",
            )
            return Response(status=status.HTTP_204_NO_CONTENT)
        except Exception as e:
            logger.error("Error removing payment method: %s", e, exc_info=True)
            return Response(
                {
                    "error": "Unable to remove payment method. Please try again or contact support."
                },
                status=status.HTTP_400_BAD_REQUEST,
            )


